changeSet.sql:
DO $$
BEGIN
    EXECUTE format(
        'ALTER DATABASE %I SET timezone TO %L',
        current_database(),
        'Asia/Shanghai'
    );
END $$;

ALTER TABLE users ALTER COLUMN created_date TYPE TIMESTAMPTZ USING created_date AT TIME ZONE 'UTC', ALTER COLUMN last_modified_date TYPE TIMESTAMPTZ USING last_modified_date AT TIME ZONE 'UTC';
ALTER TABLE resource ALTER COLUMN created_date TYPE TIMESTAMPTZ USING created_date AT TIME ZONE 'UTC', ALTER COLUMN last_modified_date TYPE TIMESTAMPTZ USING last_modified_date AT TIME ZONE 'UTC';
ALTER TABLE available_slot ALTER COLUMN created_date TYPE TIMESTAMPTZ USING created_date AT TIME ZONE 'UTC', ALTER COLUMN last_modified_date TYPE TIMESTAMPTZ USING last_modified_date AT TIME ZONE 'UTC';
ALTER TABLE reservation ALTER COLUMN reserved_at TYPE TIMESTAMPTZ USING reserved_at AT TIME ZONE 'UTC', ALTER COLUMN cancelled_at TYPE TIMESTAMPTZ USING cancelled_at AT TIME ZONE 'UTC', ALTER COLUMN completed_at TYPE TIMESTAMPTZ USING completed_at AT TIME ZONE 'UTC', ALTER COLUMN created_date TYPE TIMESTAMPTZ USING created_date AT TIME ZONE 'UTC', ALTER COLUMN last_modified_date TYPE TIMESTAMPTZ USING last_modified_date AT TIME ZONE 'UTC';
